{
  "title": "Hepatitis C Adherence and Transmission Game",
  "perWatchSecond": 3,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence threshold",
      "goal": "See if raising adherence stops the epidemic",
      "control": {
        "parameter": "theta",
        "label": "Adherence proportion",
        "lowEnd": "0.4",
        "highEnd": "0.6"
      },
      "watch": "Susceptible fraction (s)",
      "whatIf": {
        "prompt": "What if adherence rises to 60%?",
        "parameter": "theta",
        "value": 0.6
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.05
      },
      "effect": "Increasing adherence to 60% keeps about 55% susceptible versus 50% at 50%, higher by ~5% at year 200.",
      "prediction": {
        "prompt": "Predict the susceptible fraction at year 200 with 60% adherence.",
        "claimed": "Higher by about 5%",
        "other": "Lower by about 5%"
      },
      "passage": {
        "title": "Finding 0",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Higher adherence improves outcomes, useful for later scenarios."
    },
    {
      "kind": "result",
      "finding": 2,
      "title": "Re‑infection impact",
      "goal": "Test whether more re‑susceptibility changes chronic on‑treatment load",
      "control": {
        "parameter": "phi",
        "label": "Re‑susceptibility rate",
        "lowEnd": "0.0005",
        "highEnd": "0.002"
      },
      "watch": "Chronically infected on treatment (c)",
      "whatIf": {
        "prompt": "What if re‑susceptibility doubles to 0.002?",
        "parameter": "phi",
        "value": 0.002
      },
      "difference": {
        "compartment": "c",
        "summary": "mean",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.0005
      },
      "effect": "Doubling re‑susceptibility raises the average c by about 0.0005 over 200 years.",
      "prediction": {
        "prompt": "Predict the average c under higher re‑susceptibility.",
        "claimed": "Higher by about 0.0005",
        "other": "Lower by about 0.0005"
      },
      "passage": {
        "title": "Finding 2",
        "quote": "variations in re‑susceptibility minimally impact outcomes, suggesting that re‑susceptibility can often be excluded in such analyses."
      },
      "carryForward": "Now examine transmission sources."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "Quitters drive spread",
      "goal": "Observe effect of stronger transmission from quitters",
      "control": {
        "parameter": "beta3",
        "label": "Transmission from quitters",
        "lowEnd": "0.03",
        "highEnd": "0.07"
      },
      "watch": "Quitters compartment (cq)",
      "whatIf": {
        "prompt": "What if quitters transmit at 0.07?",
        "parameter": "beta3",
        "value": 0.07
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.004
      },
      "effect": "Raising β₃ to 0.07 raises the peak cq by about 0.004.",
      "prediction": {
        "prompt": "Predict the peak cq when β₃=0.07.",
        "claimed": "Higher by about 0.004",
        "other": "Lower by about 0.004"
      },
      "passage": {
        "title": "Finding 4",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Combine adherence and transmission changes."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "Boosting recovery on treatment",
      "goal": "Check if higher on‑treatment recovery raises recovered pool",
      "control": {
        "parameter": "rho",
        "label": "Recovery on treatment",
        "lowEnd": "0.05",
        "highEnd": "0.2"
      },
      "watch": "Recovered fraction (r)",
      "whatIf": {
        "prompt": "What if recovery on treatment rises to 0.19?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "r",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.01
      },
      "effect": "Setting ρ to 0.19 increases r to about 0.03 at year 200, roughly 1% higher.",
      "prediction": {
        "prompt": "Predict the recovered fraction at year 200 with ρ=0.19.",
        "claimed": "Higher by about 1%",
        "other": "Lower by about 1%"
      },
      "passage": {
        "title": "Finding 6",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that ℛ₀ falls below 1."
      },
      "carryForward": "Game ends with understanding of key levers."
    }
  ],
  "limits": [
    "All levels run for 200 years.",
    "Time per watch second set to 3 to keep playback under 20 seconds."
  ]
}
